function validate(input) {
  const [{ Contests = [], Users = [] }] = input;
  const contests = new Set(), users = new Set();
  for (const [id, gold, silver, bronze] of Contests) {
    if (id === null) return 'Every contest needs a contest_id.';
    if (contests.has(id)) return `contest_id ${id} appears twice in Contests.`;
    contests.add(id);
    if (gold === null || silver === null || bronze === null) return `Contest ${id} is missing a medalist.`;
    if (gold === silver || gold === bronze || silver === bronze) return `Contest ${id} gives two medals to one user.`;
  }
  if (contests.size) {
    const ids = [...contests];
    if (Math.max(...ids) - Math.min(...ids) + 1 !== ids.length) return 'Contest ids must be consecutive with none skipped.';
  }
  for (const [id] of Users) {
    if (id === null) return 'Every user needs a user_id.';
    if (users.has(id)) return `user_id ${id} appears twice in Users.`;
    users.add(id);
  }
  return null;
}

