function generate(rand, size) {
  const small = size === 'small';
  const names = ['Sarah', 'Bob', 'Alice', 'Hercy', 'Quarz', 'Mona', 'Ravi', 'Lena'];
  const pick = list => list[Math.floor(rand() * list.length)];
  // Small cases draw medalists from a few users so streaks and repeated golds are common.
  const pool = small ? 3 + Math.floor(rand() * 4) : 1500;
  const hot = small ? pool : 40;
  const contests = small ? Math.floor(rand() * 9) : 2000;
  const first = small ? pick([1, 190, 500]) : 1;
  const Contests = [];
  for (let i = 0; i < contests; i++) {
    const winners = [];
    while (winners.length < 3) {
      const user = 1 + Math.floor(rand() * (rand() < 0.5 ? hot : pool));
      if (!winners.includes(user)) winners.push(user);
    }
    Contests.push([first + i, ...winners]);
  }
  // Most medalists are listed in Users; a few are missing, and some users never win anything.
  const Users = [];
  for (let id = 1; id <= pool + (small ? 1 : 0); id++) {
    if (rand() < (small ? 0.85 : 0.95)) {
      const name = small ? names[(id - 1) % names.length] : `${pick(names)}${id}`;
      Users.push([id, `${name.toLowerCase()}@leetcode.com`, name]);
    }
  }
  return [{ Contests, Users }];
}
